{
  "implementation": "import math

def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        w = max(core_dist[u], core_dist[v], d)
        # Normalize order to avoid duplicate
        if u < v:
            edges.append((u, v, w))
        else:
            edges.append((v, u, w))

    # Sort edges by weight, then by first node, then second node
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find (Disjoint Set Union)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
